        4,
        'OSI Model, Networking Devices & PDU Reference Sheet: The complete seven-layer Open Systems Interconnection (OSI) matrix mapping layers to Protocol Data Units (PDUs), addressing schemes, and physical devices.',
        'Calling the Layer 2 PDU a ''packet'' or Layer 3 PDU a ''frame''. Layer 2 is Frame (MAC), Layer 3 is Packet (IP), Layer 4 is Segment/Datagram (Port).',
        '["Layer 1 (Physical): PDU = Bits; Devices = Repeater, Hub, Cables", "Layer 2 (Data Link): PDU = Frame; Addressing = 48-bit MAC; Devices = Bridge, Switch, NIC", "Layer 3 (Network): PDU = Packet; Addressing = IP (IPv4/IPv6); Devices = Router, Layer-3 Switch", "Layer 4 (Transport): PDU = Segment (TCP) / Datagram (UDP); Addressing = 16-bit Port numbers", "Layer 5 (Session): PDU = Data; Establishes and terminates sessions (RPC, NetBIOS)", "Layer 6 (Presentation): PDU = Data; Encryption (SSL/TLS), Compression, Syntax (JPEG, ASCII)", "Layer 7 (Application): PDU = Data; End-user protocols (HTTP, DNS, SMTP, FTP, SSH)"]',
        '{"questionStem": "Identify the Protocol Data Unit (PDU) and primary addressing mechanism at Layer 2 (Data Link) and Layer 3 (Network) of the OSI model.", "steps": ["Step 1: Analyze Layer 2 (Data Link Layer): The Protocol Data Unit is called a FRAME. The addressing mechanism is the 48-bit Media Access Control (MAC) address (physical address hard-burned into the NIC).", "Step 2: Analyze Layer 3 (Network Layer): The Protocol Data Unit is called a PACKET. The addressing mechanism is the logical IP address (32-bit IPv4 or 128-bit IPv6 address used for end-to-end routing)."], "finalAnswer": "$$\\text{Layer 2: Frame (MAC Address); Layer 3: Packet (IP Address)}$$", "structuredSteps": [{"stepNumber": 1, "title": "State Layer 2 PDU and Address", "explanation": "Frame and 48-bit MAC address.", "formula": "$$\\text{Layer 2} \\implies \\text{Frame, MAC}$$", "tip": "Framed with header and FCS trailer."}, {"stepNumber": 2, "title": "State Layer 3 PDU and Address", "explanation": "Packet and logical IP address.", "formula": "$$\\text{Layer 3} \\implies \\text{Packet, IP}$$", "tip": "Routable across disparate networks."}], "keyTakeaways": ["Remember OSI layers from bottom to top: Physical, Data Link, Network, Transport, Session, Presentation, Application (Please Do Not Throw Sausage Pizza Away).", "Hubs operate at Layer 1; Switches operate at Layer 2; Routers operate at Layer 3."], "quickCheckItems": [{"question": "At which layer of the OSI model do port numbers (e.g. Port 80 for HTTP, Port 443 for HTTPS) operate?", "options": ["Layer 4 (Transport Layer)", "Layer 3 (Network Layer)", "Layer 7 (Application Layer)", "Layer 2 (Data Link Layer)"], "correctOptionIndex": 0, "explanation": "Port numbers operate at Layer 4 (Transport Layer) to direct segments to specific application processes."}]}'
    )
) AS v(
    id, subject_code, topic_code, subtopic_code,
    lesson_type, difficulty_level, sequence_no, prerequisite_lesson_id,
    estimated_minutes, core_concept, trap, cheat_sheet, step_by_step_breakdown
)
JOIN question_service.subject s
  ON (s.code = v.subject_code OR s.name = v.subject_code) AND (s.tenant_id IS NULL OR s.tenant_id = 'default')
JOIN question_service.topic t
  ON (t.code = v.topic_code OR t.name = v.topic_code) AND t.subject_id = s.id AND (t.tenant_id IS NULL OR t.tenant_id = 'default')
JOIN LATERAL (
    SELECT id FROM question_service.subtopic
    WHERE topic_id = t.id AND (v.subtopic_code IS NULL OR code = v.subtopic_code OR name = v.subtopic_code)
    ORDER BY CASE WHEN code = v.subtopic_code THEN 0 WHEN name = v.subtopic_code THEN 1 ELSE 2 END, display_order ASC
    LIMIT 1
) st ON TRUE
ON CONFLICT (id) DO NOTHING;

