(
    gen_random_uuid(),
    'b1010000-0000-0000-0000-000000000023'::uuid,
    'default',
    'hi',
    'न्यूटन का द्वितीय गति नियम भौतिकी के सबसे मूलभूत सिद्धांतों में से एक है: संवेग परिवर्तन की दर लगाए गए कुल बाह्य बल के समानुपाती होती है ($$\vec{F}_{\text{net}} = \frac{d\vec{p}}{dt}$$)। यदि वस्तु का द्रव्यमान $$m$$ स्थिर रहता है, तो यह समीकरण सीधे तौर पर $$\vec{F}_{\text{net}} = m\vec{a}$$ बन जाता है।',
    'यह मानना कि बल किसी वस्तु के वेग को बनाए रखने के लिए आवश्यक है (अरस्तू का भ्रम)। बल केवल वेग में परिवर्तन (त्वरण) उत्पन्न करने के लिए आवश्यक होता है।',
    '["न्यूटन का द्वितीय नियम: $$\\vec{F}_{\\text{net}} = m\\vec{a}$$", "संवेग की परिभाषा: $$\\vec{p} = m\\vec{v}$$", "बल का आवेग: $$\\vec{J} = \\vec{F} \\Delta t = \\Delta \\vec{p}$$", "SI मात्रक: बल = न्यूटन ($$\\text{N} = \\text{kg}\\cdot\\text{m/s}^2$$), संवेग = $$\\text{kg}\\cdot\\text{m/s}$$"]'::jsonb,
    '{"questionStem": "$$5\\text{ kg}$$ द्रव्यमान की एक स्थिर वस्तु पर $$20\\text{ N}$$ का एक नियत बल $$3\\text{ सेकंड}$$ के लिए लगाया जाता है। वस्तु का अंतिम वेग और संवेग ज्ञात कीजिए।", "steps": ["चरण 1: त्वरण की गणना: $$a = \\frac{F}{m} = \\frac{20}{5} = 4\\text{ m/s}^2$$.", "चरण 2: गति के प्रथम समीकरण से अंतिम वेग: चूँकि वस्तु स्थिर अवस्था से शुरू होती है ($$u = 0$$), $$v = u + at = 0 + (4 \\times 3) = 12\\text{ m/s}$$.", "चरण 3: अंतिम संवेग की गणना: $$p = m \\times v = 5 \\times 12 = 60\\text{ kg}\\cdot\\text{m/s}$$. वैकल्पिक रूप से, आवेग $$J = F \\times \\Delta t = 20 \\times 3 = 60\\text{ N}\\cdot\\text{s}$$."], "finalAnswer": "$$v = 12\\text{ m/s}, \\quad p = 60\\text{ kg}\\cdot\\text{m/s}$$", "structuredSteps": [{"stepNumber": 1, "title": "त्वरण ज्ञात करें", "explanation": "द्रव्यमान द्वारा बल को विभाजित करें: 20 / 5 = 4 m/s^2।", "formula": "$$a = \\frac{F}{m} = 4\\text{ m/s}^2$$", "tip": "न्यूटन के द्वितीय नियम का सीधा अनुप्रयोग।"}, {"stepNumber": 2, "title": "अंतिम वेग ज्ञात करें", "explanation": "v = u + at सूत्र का प्रयोग करें: 0 + 4 * 3 = 12 m/s।", "formula": "$$v = 12\\text{ m/s}$$", "tip": "प्रारंभिक वेग शून्य है।"}, {"stepNumber": 3, "title": "संवेग निर्धारित करें", "explanation": "द्रव्यमान और वेग का गुणनफल लें।", "formula": "$$p = 60\\text{ kg}\\cdot\\text{m/s}$$", "tip": "आवेग संवेग परिवर्तन के बराबर होता है।"}], "keyTakeaways": ["नियत द्रव्यमान के लिए बल हमेशा त्वरण उत्पन्न करता है।", "बल का आवेग सीधे संवेग में परिवर्तन के बराबर होता है।"], "quickCheckItems": [{"question": "यदि 2 kg द्रव्यमान पर 10 N का बल लगाया जाए, तो उत्पन्न त्वरण क्या होगा?", "options": ["$$5\\text{ m/s}^2$$", "$$20\\text{ m/s}^2$$", "$$0.2\\text{ m/s}^2$$", "$$8\\text{ m/s}^2$$"], "correctOptionIndex": 0, "explanation": "$$a = \\frac{F}{m} = \\frac{10}{2} = 5\\text{ m/s}^2$$."}]}'::jsonb,
