    'b1010000-0000-0000-0000-000000000030'::uuid,
    'default',
    'hi',
    'भारतीय रिज़र्व बैंक (RBI) की मौद्रिक नीति तरलता समायोजन सुविधा (LAF) के माध्यम से मुद्रा आपूर्ति और अल्पकालिक ब्याज दरों को नियंत्रित करती है। नीतिगत रेपो दर (Repo Rate) वह ब्याज दर है जिस पर RBI वाणिज्यिक बैंकों को सरकारी प्रतिभूतियों के बदले अल्पकालिक ऋण प्रदान करता है। मुद्रास्फीति नियंत्रण के लिए रेपो दर बढ़ाई जाती है, जिससे ऋण महंगा होता है।',
    'यह मानना कि रिवर्स रेपो दर अभी भी LAF कॉरिडोर का मुख्य निचला स्तर (Floor) है। अप्रैल 2022 से स्टैंडिंग डिपॉजिट फैसिलिटी (SDF) ने इसका स्थान ले लिया है, जो बिना संपार्श्विक के काम करती है।',
    '["रेपो दर (Repo Rate): RBI द्वारा बैंकों को अल्पकालिक संपार्श्विक ऋण की दर", "एसडीएफ (SDF): तरलता अवशोषण की संपार्श्विक-मुक्त निचली सीमा ($$\\text{रेपो} - 0.25\\%$$)", "एमएसएफ (MSF): आपातकालीन रातों-रात उधार की ऊपरी सीमा ($$\\text{रेपो} + 0.25\\%$$)", "सीआरआर (CRR): RBI अधिनियम 1934 की धारा 42 के तहत नकद शेष (शून्य ब्याज)", "एसएलआर (SLR): बैंकिंग विनियमन अधिनियम 1949 की धारा 24 के तहत तरल आस्तियां"]'::jsonb,
    '{"questionStem": "यदि मौद्रिक नीति समिति (MPC) रेपो दर को $$6.50\\%$$ पर निर्धारित करती है, तो प्रचलित SDF और MSF दरें क्या होंगी?", "steps": ["चरण 1: LAF कॉरिडोर संरचना: SDF और MSF दरें रेपो दर के क्रमशः $$25\\text{ आधार अंक}$$ नीचे और ऊपर सममित रूप से स्थित होती हैं।", "चरण 2: SDF दर की गणना: $$\\text{SDF} = 6.50\\% - 0.25\\% = 6.25\\%$$.", "चरण 3: MSF दर की गणना: $$\\text{MSF} = 6.50\\% + 0.25\\% = 6.75\\%$$. कॉरिडोर का विस्तार $$50\\text{ आधार अंक}$$ है।"], "finalAnswer": "$$\\text{SDF} = 6.25\\%, \\quad \\text{MSF} = 6.75\\%$$", "structuredSteps": [{"stepNumber": 1, "title": "कॉरिडोर सीमाएं निर्धारित करें", "explanation": "SDF रेपो से 25 bps कम है और MSF 25 bps अधिक है।", "formula": "$$\\pm 25\\text{ bps}$$", "tip": "कॉरिडोर की चौड़ाई 50 bps है।"}, {"stepNumber": 2, "title": "SDF दर निकालें", "explanation": "6.50% - 0.25% = 6.25%।", "formula": "$$\\text{SDF} = 6.25\\%$$", "tip": "तरलता सोखने की न्यूनतम दर।"}, {"stepNumber": 3, "title": "MSF दर निकालें", "explanation": "6.50% + 0.25% = 6.75%।", "formula": "$$\\text{MSF} = 6.75\\%$$", "tip": "दंडात्मक रातों-रात उधार खिड़की।"}], "keyTakeaways": ["SDF अतिरिक्त तरलता को बिना सरकारी प्रतिभूतियों के अवशोषित करता है।", "मौद्रिक नीति समिति (MPC) में 6 सदस्य होते हैं और गवर्नर के पास निर्णायक वोट होता है।"], "quickCheckItems": [{"question": "SDF का पूर्ण रूप क्या है?", "options": ["Standing Deposit Facility", "Secured Deposit Fund", "Standard Discount Function", "Statutory Deposit Framework"], "correctOptionIndex": 0, "explanation": "SDF का पूर्ण रूप Standing Deposit Facility (स्थायी जमा सुविधा) है।"}]}'::jsonb,
